-- ============================================================
-- 149_curriculum_tde_tymm2026_agac.sql
-- Altın Kalemler — CURRICULUM-ALL-01 TDE dilimi: TYMM 2026 Türk Dili ve
--   Edebiyatı müfredat ağacının (16 tema + 64 İçerik Çerçevesi maddesi +
--   246 çatı-kodlu outcome) YÜKLENMESİ ve tymm_2026_tde sürüm satırı.
--
-- KULLANICI ONAYLI KAPSAM (2026-10-28; tde-yukleme-onay-paketi.md)
--   - 1 sürüm + 16 topic + 64 subtopic + 246 outcome (9: 4/16/54; 10: 4/16/64; 11: 4/16/64; 12: 4/16/64).
--   - outcome_code = HAM resmî çatı kodu (S1 sözleşmesi; migration 148 ile canlı
--     bileşik partial UNIQUE indeks benzersizliği korur). Kodlar temalar arası
--     TEKRAR EDER (resmî yapı); tema bağlamı topic_id kolonunda yaşar.
--   - subtopic_id = 246/246 NULL (kaynakta numaralandırılmamış; BLOKAJ-1 kuralı).
--   - TDE ADAY ALIMI KAPALI KALIR (bu migration yalnız müfredat verisidir).
--
-- KAYNAK (yalnız resmî)
--   Türkiye Yüzyılı Maarif Modeli — Ortaöğretim Türk Dili ve Edebiyatı Dersi (Hazırlık, 9, 10, 11 ve 12. Sınıflar) Öğretim Programı (2026)
--   Yerel: docs/references/mufredat/2026-2027/tymm-2026-turk-dili-ve-edebiyati.pdf (SHA256 a04e1444…dd13a)
--   Ağaç:  docs/question-production/curriculum-mapping/tde-9-12-kanonik-esleme-v1.md
--   Dry-run: scripts/mufredat-dry-run.ts --ders=tde → tde-dry-run-sonuc.md
--   (326 veri satırı, 16/64/246, eşleşen 0, metin farkı 0, engelli 0)
--   Üretici: evidence/a149-uygulama-20261028/gen149.mjs (aynı ayrıştırıcı; bu dosya ELLE DÜZENLENMEZ)
--
-- UUID ŞEMASI (146 deseni; aileler DB envanteriyle çakışmasız — d% = 0/0/0 doğrulandı 2026-10-28):
--   topic: d1+GG | subtopic: d2+GG | outcome: d3+GG; NN = sınıf içi kesintisiz sayaç.
--   Mevcut aileler: a3/a5/b1/b4/b7/c1/c4 topics; a6/a8/b2/b5/b8/c2/c5 subtopics;
--   a7/a9/b3/b6/b9/c3/c6 outcomes. Sürüm id: a1 ailesinde c9 (c1..c8 dolu).
--   Subject id: 33f52f3a-8032-449e-85db-0bffddec8d06 (Edebiyat).
--
-- SIRA KARARLARI (kayıtlı): topic.sort_order=tema no; subtopic.sort_order=sınıf içi
--   kesintisiz kutu sırası; outcome.sort_order=TEMA İÇİ basılı sıra (çatı kodda
--   ünite-içi k alanı yoktur — 146 "k" şemasının TDE uyarlaması; sıra kanonik §4).
--   source_reference: 'TYMM 2026 Türk Dili ve Edebiyatı Öğretim Programı, s.NN' (kanonik satırın kaynak sayfası).
--
-- İDEMPOTENCE: tüm INSERT'ler ON CONFLICT (id) DO NOTHING; GUARD ağacı ya (0,0,0)
--   ya (16/64/246) kabul eder; history version='149' WHERE NOT EXISTS.
--
-- GERİ DÖNÜŞ: evidence/a149-uygulama-20261028/geri-donus.sql (246 outcome DELETE →
--   64 subtopic DELETE → 16 topic DELETE → sürüm DELETE → history DELETE; fail-closed
--   üçüncü-taraf referans taraması; 148 geri dönüşünden BAĞIMSIZDIR — veri silme
--   yalnız bu migration'ın kendi id kümesiyle sınırlıdır; bağlı kayıtlar varsa DURUR).
--
-- YASAKLAR: TDE aday alımı açılmaz; 148'in fonksiyon/indeks/izinlerine dokunulmaz;
--   mevcut 7 ders + matematik/fizik/kimya/biyoloji/coğrafya/tarih/felsefe ailelerine
--   dokunulmaz; şema/RLS değişmez (data-only). commit/push YOK.
-- ============================================================

BEGIN;

-- ============================================================
-- 0. ÖN-KOŞUL DENETİMİ (fail-closed)
-- ============================================================
DO $guard$
DECLARE
  v_topic_sayi integer;
  v_subtopic_sayi integer;
  v_outcome_sayi integer;
  v_surum integer;
  v_yabanci integer;
  v_tanimli integer;
  v_benzersiz integer;
  v_cati integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.subjects WHERE id = '33f52f3a-8032-449e-85db-0bffddec8d06') THEN
    RAISE EXCEPTION 'GUARD_149: Edebiyat subject satırı yok.';
  END IF;

  -- Sürüm satırı: ya hiç yok (ilk uygulama) ya da TAM bu çift var (tekrar koşum)
  SELECT count(*) INTO v_surum FROM public.curriculum_versions
   WHERE framework = 'tymm_2026_tde' OR id = 'a1000000-0000-4000-8000-0000000000c9';
  IF v_surum > 0 THEN
    IF NOT EXISTS (SELECT 1 FROM public.curriculum_versions
                   WHERE id = 'a1000000-0000-4000-8000-0000000000c9' AND framework = 'tymm_2026_tde'
                     AND academic_year = '2026-2027' AND is_default = false) THEN
      RAISE EXCEPTION 'GUARD_149: sürüm satırı çelişkili — fail-closed dur.';
    END IF;
  END IF;

  -- Ağaç durumu: ya boş (ilk uygulama) ya tam dolu (tekrar koşum). Kısmi/yabancı fail-closed.
  SELECT count(*) INTO v_topic_sayi FROM public.topics WHERE subject_id = '33f52f3a-8032-449e-85db-0bffddec8d06';
  SELECT count(*) INTO v_subtopic_sayi FROM public.subtopics s
   JOIN public.topics t ON t.id = s.topic_id WHERE t.subject_id = '33f52f3a-8032-449e-85db-0bffddec8d06';
  SELECT count(*) INTO v_outcome_sayi FROM public.curriculum_outcomes WHERE outcome_code LIKE 'TDE%';
  IF NOT (v_topic_sayi = 0 AND v_subtopic_sayi = 0 AND v_outcome_sayi = 0)
     AND NOT (v_topic_sayi = 16 AND v_subtopic_sayi = 64 AND v_outcome_sayi = 246) THEN
    RAISE EXCEPTION 'GUARD_149: TDE ağacı kısmi/yabancı durumda (topics=%, subtopics=%, outcomes=%; beklenen 0/0/0 veya 16/64/246) — fail-closed dur.', v_topic_sayi, v_subtopic_sayi, v_outcome_sayi;
  END IF;

  IF v_topic_sayi = 0 THEN
    -- İlk uygulama: d% UUID aileleri BOŞ olmalı (çakışmasız aile seçiminin koruması)
    SELECT count(*) INTO v_yabanci FROM public.topics WHERE id::text LIKE 'd%';
    IF v_yabanci > 0 THEN RAISE EXCEPTION 'GUARD_149: d%% topics ailesi dolu (%) — fail-closed.', v_yabanci; END IF;
    SELECT count(*) INTO v_yabanci FROM public.subtopics WHERE id::text LIKE 'd%';
    IF v_yabanci > 0 THEN RAISE EXCEPTION 'GUARD_149: d%% subtopics ailesi dolu (%) — fail-closed.', v_yabanci; END IF;
    SELECT count(*) INTO v_yabanci FROM public.curriculum_outcomes WHERE id::text LIKE 'd%';
    IF v_yabanci > 0 THEN RAISE EXCEPTION 'GUARD_149: d%% outcomes ailesi dolu (%) — fail-closed.', v_yabanci; END IF;
  END IF;

