    END IF;
    SELECT count(*) INTO v_yabanci FROM public.subtopics s
     JOIN public.topics t ON t.id = s.topic_id
     WHERE t.subject_id = '33f52f3a-8032-449e-85db-0bffddec8d06' AND s.id NOT IN (
        'd2090000-0000-4000-8000-000000000001',
