        'd3120000-0000-4000-8000-000000000056',
        'd3120000-0000-4000-8000-000000000057',
        'd3120000-0000-4000-8000-000000000058',
        'd3120000-0000-4000-8000-000000000059',
        'd3120000-0000-4000-8000-000000000060',
        'd3120000-0000-4000-8000-000000000061',
        'd3120000-0000-4000-8000-000000000062',
        'd3120000-0000-4000-8000-000000000063',
        'd3120000-0000-4000-8000-000000000064'
    )), count(DISTINCT outcome_code) INTO v_outcome_sayi, v_tanimli, v_benzersiz
      FROM public.curriculum_outcomes WHERE outcome_code LIKE 'TDE%';
    IF v_outcome_sayi <> 246 OR v_tanimli <> 246 OR v_benzersiz <> 16 THEN
      RAISE EXCEPTION 'GUARD_149: TDE outcomes=% (tanınan=%, ayrık kod=%; beklenen 246/246/16) — id/kod drifti, fail-closed dur.', v_outcome_sayi, v_tanimli, v_benzersiz;
    END IF;
    -- S1 sözleşmesi: (sürüm, sınıf, tema, kod) üçlüsü benzersiz (148 indeksiyle uyum)
    SELECT count(*) INTO v_cati FROM (
      SELECT 1 FROM public.curriculum_outcomes
       WHERE outcome_code LIKE 'TDE%' AND topic_id IS NOT NULL
       GROUP BY curriculum_version_id, grade_level, topic_id, outcome_code
       HAVING count(*) > 1
    ) x;
    IF v_cati <> 0 THEN
      RAISE EXCEPTION 'GUARD_149: çatı üçlüsünde % mükerrer (sürüm,sınıf,tema,kod) — fail-closed dur.', v_cati;
    END IF;
  END IF;
END
$guard$;

