DO $final$
DECLARE
  v_topic integer; v_subtopic integer; v_outcome integer;
  v_cati_muk integer; v_null_sub integer; v_sonra_sinif integer;
BEGIN
  SELECT count(*) INTO v_topic FROM public.topics WHERE subject_id = '33f52f3a-8032-449e-85db-0bffddec8d06';
  SELECT count(*) INTO v_subtopic FROM public.subtopics s
   JOIN public.topics t ON t.id = s.topic_id WHERE t.subject_id = '33f52f3a-8032-449e-85db-0bffddec8d06';
  SELECT count(*) INTO v_outcome FROM public.curriculum_outcomes WHERE outcome_code LIKE 'TDE%';
  IF (v_topic, v_subtopic, v_outcome) <> (16, 64, 246) THEN
    RAISE EXCEPTION 'FINAL_149: sayılar %/%/% (beklenen 16/64/246) — ROLLBACK.', v_topic, v_subtopic, v_outcome;
  END IF;
  SELECT count(*) INTO v_cati_muk FROM (
    SELECT 1 FROM public.curriculum_outcomes
     WHERE outcome_code LIKE 'TDE%' AND topic_id IS NOT NULL
     GROUP BY curriculum_version_id, grade_level, topic_id, outcome_code
     HAVING count(*) > 1
  ) x;
  IF v_cati_muk <> 0 THEN
    RAISE EXCEPTION 'FINAL_149: çatı üçlüsü mükerrer % — ROLLBACK.', v_cati_muk;
  END IF;
  SELECT count(*) INTO v_null_sub FROM public.curriculum_outcomes
   WHERE outcome_code LIKE 'TDE%' AND subtopic_id IS NOT NULL;
  IF v_null_sub <> 0 THEN
    RAISE EXCEPTION 'FINAL_149: subtopic_id NULL sözleşmesi bozuldu (%) — ROLLBACK.', v_null_sub;
  END IF;
  -- 246/246 topic bağlantısı TDE sürümüne mi (izolasyon)
  SELECT count(*) INTO v_sonra_sinif FROM public.curriculum_outcomes
   WHERE outcome_code LIKE 'TDE%'
     AND (topic_id IS NULL OR curriculum_version_id <> 'a1000000-0000-4000-8000-0000000000c9' OR subject_id <> '33f52f3a-8032-449e-85db-0bffddec8d06');
  IF v_sonra_sinif <> 0 THEN
    RAISE EXCEPTION 'FINAL_149: % satır sürüm/subject izolasyonu dışında — ROLLBACK.', v_sonra_sinif;
  END IF;
END
$final$;

-- ============================================================
-- 5. HISTORY — idempotent (146/147/148 deseni)
-- ============================================================
insert into supabase_migrations.schema_migrations (version, name, statements)
select '149', '149_curriculum_tde_tymm2026_agac', NULL
 where not exists (
   select 1 from supabase_migrations.schema_migrations where version = '149'
 );

COMMIT;
